PAD, BOS, EOS = 0, 1, 2
CABN = 4

def make_bias(cab, adj, neg=-1e9):
    same = cab[:, None] == cab[None, :]
    adjm = torch.zeros_like(same)
    for (i, j) in adj:
        adjm |= ((cab[:, None] == i) & (cab[None, :] == j)) | ((cab[:, None] == j) & (cab[None, :] == i))
    b = torch.full((cab.numel(), cab.numel()), neg, device=cab.device)
    b = torch.where(adjm, torch.full_like(b, -2.0), b)
    return torch.where(same, torch.zeros_like(b), b)

class Blk(nn.Module):
    def __init__(s, d, h):
        super().__init__(); s.h = h; s.d = d
        s.qkv = nn.Linear(d, 3 * d, bias=False); s.pr = nn.Linear(d, d)
        s.n1, s.n2 = nn.RMSNorm(d), nn.RMSNorm(d)
        ff = int(8 / 3 * d) // 64 * 64
        s.g, s.u, s.dw = nn.Linear(d, ff), nn.Linear(d, ff), nn.Linear(ff, d)
    def fwd(s, x, bias, cos, sin):
        B, T, d = x.shape
        q, k, v = s.qkv(s.n1(x)).split(d, 2)
        q, k, v = (t.view(B, T, s.h, d // s.h).transpose(1, 2) for t in (q, k, v))
        rp = lambda t: t * cos + torch.cat((-t[..., t.size(-1)//2:], t[..., :t.size(-1)//2]), -1) * sin
        q, k = rp(q), rp(k)
        x = x + s.pr(F.scaled_dot_product_attention(q, k, v, attn_mask=bias).transpose(1, 2).reshape(B, T, d))
        h = s.n2(x)
        return x + s.dw(F.silu(s.g(h)) * s.u(h))

class M(nn.Module):
    def __init__(s, V, d=384, L=6, h=8, ctx=512):
        super().__init__(); s.ctx = ctx
        s.emb = nn.Embedding(V, d); nn.init.normal_(s.emb.weight, std=0.02)
        s.bl = nn.ModuleList([Blk(d, h) for _ in range(L)])
        s.head = nn.Linear(d, V, bias=False); s.head.weight = s.emb.weight
        dh = d // h; p = torch.arange(ctx)
        f = 1.0 / (10000 ** (torch.arange(0, dh // 2).float() * 2 / dh))
        fr = torch.cat([p[:, None] * f[None, :]] * 2, -1)
        s.register_buffer("cos", fr.cos()[None, None]); s.register_buffer("sin", fr.sin()[None, None])
    def forward(s, idx, cab, bias):
        x = s.emb(idx); T = idx.size(1)
        for b in s.bl: x = b.fwd(x, bias, s.cos[:, :, :T], s.sin[:, :, :T])
        return s.head(x)

chars = sorted({c for t, _ in DOCS for c in t})
ITOS = ["<p>", "<b>", "<e>"] + chars; STOI = {c: i for i, c in enumerate(ITOS)}
def enc(t): return [BOS] + [STOI[c] for c in t if c in STOI] + [EOS]  # OOV 容忍(探针字可越库)

def pack(seed, cabins=None, ctx=512, batch=16):
    ds = [d for d in DOCS if cabins is None or d[1] in cabins]
    random.Random(seed).shuffle(ds)
    tk, cb = [], []
    for t, c in ds:
        e = enc(t); tk += e; cb += [c] * len(e)
    rows = (len(tk) - 1) // ctx
    a = torch.tensor(tk[:rows * ctx + 1]); v = torch.tensor(cb[:rows * ctx + 1])
    return (a[:rows*ctx].view(rows, ctx).to(DEV), v[:rows*ctx].view(rows, ctx).to(DEV),
            a[1:rows*ctx+1].view(rows, ctx).to(DEV))

def stage(step, total, curr):
    if not curr: return {0, 1, 2, 3}, {(0, 1), (2, 3)}
    if step < .4 * total: return {0, 1}, set()
    if step < .7 * total: return {0, 1, 2, 3}, {(0, 1)}
    return {0, 1, 2, 3}, {(0, 1), (2, 3)}

CAUS = torch.full((512, 512), -1e9, device=DEV).triu(1)

def train(arm, steps=2500, curr=True, seed=0):
    torch.manual_seed(seed); random.seed(seed)
    m = M(len(ITOS)).to(DEV)
    tbl = torch.zeros(CABN, CABN, device=DEV, requires_grad=(arm == "learned"))
    opt = torch.optim.AdamW(m.parameters(), lr=3e-4, weight_decay=0.1)
    if arm == "learned": opt.add_param_group({"params": [tbl]})
    g = torch.Generator().manual_seed(7)
    rperm = torch.randperm(CABN, generator=g)
    t0 = time.time(); lg = []
    step = 0
    while step < steps:
        cabins, adj = stage(step, steps, curr)
        X, C, Y = pack(seed + step, cabins)
        for i in range(0, X.size(0), 16):
            xb, cb, yb = X[i:i+16], C[i:i+16], Y[i:i+16]
            bs = []
            for b in range(cb.size(0)):
                r = cb[b]
                if arm == "free": bias = torch.zeros_like(CAUS[:len(r)][:len(r)])
                elif arm == "given": bias = make_bias(r, adj)
                elif arm == "random": bias = make_bias(rperm[r], adj)
                elif arm == "learned": bias = tbl[r][:, r]
                elif arm == "no-curr": bias = make_bias(r, {(0, 1), (2, 3)})
                bs.append(bias + CAUS[:len(r)][:len(r)])
            bias = torch.stack(bs)[:, None]
            loss = F.cross_entropy(m(xb, cb, bias).view(-1, len(ITOS)), yb.view(-1), ignore_index=PAD)
            opt.zero_grad(set_to_none=True); loss.backward()
            torch.nn.utils.clip_grad_norm_(m.parameters(), 1.0); opt.step()
            lg.append(loss.item()); step += 1
            if step >= steps: break
    print(f"[{arm}{'/no-curr' if not curr and arm!='given' else ''}] loss {lg[0]:.2f}->{sum(lg[-200:])/200:.3f} "
          f"wall {time.time()-t0:.0f}s", flush=True)
    return m

PROBES = [
    ("除夕夜，全家围坐吃年夜饭，饭后开始", [("守岁",0),("烧烤",1),("选秀",2),("彩虹",3)], "守岁", "空间"),
    ("夏天晚上，院子里摆开小桌，喝冰啤酒吃", [("饺子",0),("烧烤",1),("红包",0),("燕巢",3)], "烧烤", "空间"),
    ("我们给长辈发", [("红包",0),("球票",2),("烤串",1),("字典",3)], "红包", "锚点"),
    ("2003年选秀第1顺位是", [("蒂姆·邓肯",2),("勒布朗·詹姆斯",2),("迈克·毕比",2),("昌西·比卢普斯",2)], "勒布朗·詹姆斯", "序敏"),
    ("2003年选秀第3顺位是", [("卡梅隆·安东尼",2),("德维恩·韦德",2),("克里斯·波什",2),("蒂姆·邓肯",2)], "克里斯·波什", "序敏"),
    ("1997年选秀第1顺位是", [("蒂姆·邓肯",2),("迈克·奥洛沃坎迪",2),("勒布朗·詹姆斯",2),("昌西·比卢普斯",2)], "蒂姆·邓肯", "序敏"),
    ("鲸不是鱼，它是", [("哺乳动物",3),("爬行动物",3),("鱼类",3),("鸟类",3)], "哺乳动物", "验收"),
    ("零乘任何数都", [("得零",3),("得原数",3),("得一",3),("无意义",3)], "得零", "验收"),
    ("春天来了，从南方飞回来的是", [("燕子",3),("蝙蝠",3),("喜鹊",3),("蜻蜓",3)], "燕子", "验收"),
]

def paper(m, arm):
    def lp(text):
        ids = enc(text); x = torch.tensor([ids], device=DEV)
        cab = torch.tensor([[0]*len(ids)], device=DEV)
        bias = (make_bias(cab[0], set()) if arm in ("given","random") else torch.zeros(len(ids), len(ids), device=DEV)) + CAUS[:len(ids)][:len(ids)]
        with torch.no_grad():
            l = m(x, cab, bias[None, None])[:, :-1].log_softmax(-1)
        return l.gather(-1, torch.tensor(ids[1:], device=DEV).view(1, -1, 1)).sum().item()
    st = sh = 0; det = []
    for pr, cs, gd, ax in PROBES:
        b = lp(pr); w, wc = max(cs, key=lambda c: lp(pr + c[0]) - b)
        gc = next(c for x, c in cs if x == gd)
        s, h = w == gd, wc == gc; st += s; sh += h
        det.append(f"{ax}:{'✓' if s else '✗'}{'架' if h else '偏'}")
    print(f"  G3-Paper[{arm}] 字面 {st}/9 落架 {sh}/9 | " + " ".join(det), flush=True)

for arm in ["given", "free", "random", "learned"]:
    mm = train(arm)
    paper(mm, arm)
    del mm; torch.cuda.empty_cache() if DEV.type == "cuda" else None
mm = train("given", curr=False)
paper(mm, "given")
print("套件完毕, 日志即幸存者", flush=True)
